// The I/O runtime, compiled ahead of time and packaged with the compiler: the
// code and its relocations, per architecture, as pypl4g's runtime/__init__.py
// describes them.  The data is generated by bin/pl4g-runtime from runtime/io.c,
// beside pypl4g's own copy of it; a test recompiles the C and compares both.
#pragma once

#include <cstdint>
#include <optional>
#include <span>
#include <string_view>
#include <utility>


namespace pl4g::rt {

  // One section of the compiled runtime, as bytes and how to place them.
  struct Piece {
    std::string_view name;
    std::span<const unsigned char> contents;
    std::uint64_t alignment = 1;
    bool writable = false;
    bool executable = false;
  };

  // One place in a piece to fill in once the pieces have addresses: which
  // piece holds the bytes and where, the fixup it is (by the target's name for
  // it), which piece the value is measured to and how far into it, and how far
  // from this patch it is measured where that is not from the patch itself.
  struct Patch {
    std::uint32_t piece = 0;
    std::uint64_t offset = 0;
    std::string_view kind;
    std::uint32_t target = 0;
    std::int64_t addend = 0;
    std::int64_t measured_from = 0;
  };

  // Where a name the language may reach is: which piece, and how far in.
  struct Named {
    std::string_view name;
    std::uint32_t piece = 0;
    std::uint64_t offset = 0;
  };

  // The whole of the runtime for one architecture.
  struct Blob {
    std::string_view triple;
    std::span<const Piece> pieces;
    // Sorted by name.
    std::span<const Named> symbols;
    std::span<const Patch> patches;

    // Where `name` is, if this runtime defines it.
    std::optional<std::pair<std::uint32_t, std::uint64_t>> find(std::string_view name) const noexcept
    {
      for (const auto& one : symbols)
        if (one.name == name)
          return std::pair{ one.piece, one.offset };
      return std::nullopt;
    }
  };

  // The runtime built for `architecture`, or nothing where there is none.
  const Blob* blob_for(std::string_view architecture) noexcept;

} // namespace pl4g::rt
